"use client"

import * as React from "react"
import {
  addMonths,
  format,
  isAfter,
  isBefore,
  setMonth,
  setYear,
  startOfMonth,
} from "date-fns"
import { CalendarDays, ChevronDown, ChevronLeft, ChevronRight } from "lucide-react"
import { DayPicker, type Matcher } from "react-day-picker"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"

export type DateRangePickerValue = {
  from?: Date
  to?: Date
}

export interface DateRangePickerProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "value" | "defaultValue" | "onChange"> {
  value?: DateRangePickerValue
  defaultValue?: DateRangePickerValue
  onValueChange?: (value: DateRangePickerValue | undefined) => void
  wrapperClassName?: string
  popoverClassName?: string
  popoverSide?: React.ComponentPropsWithoutRef<typeof PopoverContent>["side"]
  popoverAvoidCollisions?: boolean
  placeholder?: string
  dateFormat?: string
  minYear?: number
  maxYear?: number
}

const DEFAULT_FORMAT = "dd/MM/yyyy"
const DEFAULT_PLACEHOLDER = "DD/MM/YYYY - DD/MM/YYYY"
const MONTH_LABELS = Array.from({ length: 12 }, (_, monthIndex) =>
  new Date(2020, monthIndex, 1).toLocaleString("default", { month: "long" })
)

const clampMonth = (month: Date, minMonth: Date, maxMonth: Date) => {
  if (isBefore(month, minMonth)) {
    return minMonth
  }

  if (isAfter(month, maxMonth)) {
    return maxMonth
  }

  return month
}

const normalizeRange = (
  value?: DateRangePickerValue
): DateRangePickerValue | undefined => {
  if (!value?.from && !value?.to) {
    return undefined
  }

  if (value.from && value.to && isAfter(value.from, value.to)) {
    return {
      from: value.to,
      to: value.from,
    }
  }

  return {
    from: value.from,
    to: value.to,
  }
}

const formatDate = (date: Date | undefined, dateFormat: string) => {
  if (!date) {
    return undefined
  }

  return format(date, dateFormat)
}

const formatCommittedValue = (
  value: DateRangePickerValue | undefined,
  dateFormat: string
) => {
  const fromText = formatDate(value?.from, dateFormat)
  const toText = formatDate(value?.to, dateFormat)

  if (!fromText || !toText) {
    return ""
  }

  return `${fromText} - ${toText}`
}

const formatDraftValue = (
  value: DateRangePickerValue | undefined,
  dateFormat: string
) => {
  const fromText = formatDate(value?.from, dateFormat) ?? "DD/MM/YYYY"
  const toText = formatDate(value?.to, dateFormat) ?? "DD/MM/YYYY"

  return `${fromText} - ${toText}`
}

type CalendarPanelProps = {
  label: string
  month: Date
  minMonth: Date
  maxMonth: Date
  minDate: Date
  maxDate: Date
  selectedDate?: Date
  disabledMatcher?: Matcher
  disabled?: boolean
  years: number[]
  onMonthChange: (month: Date) => void
  onSelectDate: (date: Date | undefined) => void
}

function CalendarPanel({
  label,
  month,
  minMonth,
  maxMonth,
  minDate,
  maxDate,
  selectedDate,
  disabledMatcher,
  disabled,
  years,
  onMonthChange,
  onSelectDate,
}: CalendarPanelProps) {
  const handlePrevMonth = () => {
    onMonthChange(addMonths(month, -1))
  }

  const handleNextMonth = () => {
    onMonthChange(addMonths(month, 1))
  }

  const isPrevDisabled = disabled || !isAfter(month, minMonth)
  const isNextDisabled = disabled || !isBefore(month, maxMonth)

  return (
    <div className="w-full min-w-0">
      <div className="flex flex-wrap items-center gap-2 sm:flex-nowrap">
        <button
          type="button"
          onClick={handlePrevMonth}
          disabled={isPrevDisabled}
          className={cn(
            "inline-flex h-8 w-8 items-center justify-center rounded-md text-[#6e6d71] transition-colors lg:h-9 lg:w-9",
            "hover:bg-[#f5f5f5] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#1d1c20]/20",
            "disabled:cursor-not-allowed disabled:opacity-40"
          )}
          aria-label={`Previous month for ${label.toLowerCase()}`}
        >
          <ChevronLeft className="h-4 w-4 lg:h-5 lg:w-5" />
        </button>

        <div className="relative min-w-0 flex-1">
          <select
            value={month.getMonth()}
            onChange={(event) => {
              const monthValue = Number(event.target.value)
              onMonthChange(setMonth(month, monthValue))
            }}
            disabled={disabled}
            className={cn(
              "h-9 w-full appearance-none rounded-md border border-[#b7b7b9] bg-white px-3 pr-8 text-left text-sm font-medium leading-5 text-[#111111] lg:h-10 lg:px-4 lg:pr-10",
              "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#1d1c20]/20",
              "disabled:cursor-not-allowed disabled:bg-[#f2f2f2] disabled:text-[#b3b3b3]"
            )}
            aria-label={`Month for ${label.toLowerCase()}`}
          >
            {MONTH_LABELS.map((monthLabel, monthIndex) => (
              <option key={monthLabel} value={monthIndex}>
                {monthLabel}
              </option>
            ))}
          </select>
          <ChevronDown className="pointer-events-none absolute right-2.5 top-1/2 h-4 w-4 -translate-y-1/2 text-[#7f7d83] lg:right-3" />
        </div>

        <div className="relative w-[104px] shrink-0 sm:w-[120px]">
          <select
            value={month.getFullYear()}
            onChange={(event) => {
              const yearValue = Number(event.target.value)
              onMonthChange(setYear(month, yearValue))
            }}
            disabled={disabled}
            className={cn(
              "h-9 w-full appearance-none rounded-md border border-[#b7b7b9] bg-white px-3 pr-8 text-left text-sm font-medium leading-5 text-[#111111] lg:h-10 lg:px-4 lg:pr-9",
              "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#1d1c20]/20",
              "disabled:cursor-not-allowed disabled:bg-[#f2f2f2] disabled:text-[#b3b3b3]"
            )}
            aria-label={`Year for ${label.toLowerCase()}`}
          >
            {years.map((year) => (
              <option key={year} value={year}>
                {year}
              </option>
            ))}
          </select>
          <ChevronDown className="pointer-events-none absolute right-2.5 top-1/2 h-4 w-4 -translate-y-1/2 text-[#7f7d83] lg:right-3" />
        </div>

        <button
          type="button"
          onClick={handleNextMonth}
          disabled={isNextDisabled}
          className={cn(
            "inline-flex h-8 w-8 items-center justify-center rounded-md text-[#6e6d71] transition-colors lg:h-9 lg:w-9",
            "hover:bg-[#f5f5f5] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#1d1c20]/20",
            "disabled:cursor-not-allowed disabled:opacity-40"
          )}
          aria-label={`Next month for ${label.toLowerCase()}`}
        >
          <ChevronRight className="h-4 w-4 lg:h-5 lg:w-5" />
        </button>
      </div>

      <p className="mt-1.5 text-center text-sm font-medium leading-5 text-[#666666] lg:mt-2">
        {label}
      </p>

      <DayPicker
        mode="single"
        month={month}
        onMonthChange={onMonthChange}
        selected={selectedDate}
        onSelect={onSelectDate}
        showOutsideDays
        fixedWeeks
        hideNavigation
        disabled={[
          { before: minDate },
          { after: maxDate },
          ...(disabledMatcher ? [disabledMatcher] : []),
        ]}
        className="mt-1 p-0 [--drp-cell-size:1.625rem] md:[--drp-cell-size:1.875rem] xl:[--drp-cell-size:2.125rem]"
        classNames={{
          root: "w-full",
          months: "w-full",
          month: "w-full",
          month_caption: "hidden",
          month_grid: "w-full border-collapse",
          weekdays: "grid grid-cols-7",
          weekday:
            "h-[calc(var(--drp-cell-size)-0.25rem)] text-center text-[11px] font-medium leading-4 text-[#666666] lg:text-xs",
          weeks: "grid gap-0",
          week: "grid grid-cols-7",
          day: "flex h-[var(--drp-cell-size)] w-full items-center justify-center p-0",
          day_button:
            "h-[--drp-cell-size] w-[--drp-cell-size] rounded-md border border-transparent bg-transparent p-0 text-[13px] font-normal leading-none text-[#444444] transition-colors hover:border-[#cccccc] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#2bbd8f]/25 lg:text-sm",
          selected:
            "[&>button]:border-[#2bbd8f] [&>button]:bg-[#2bbd8f] [&>button]:text-[#111111]",
          today: "font-medium",
          outside: "text-[#a4a4a8]",
          disabled: "pointer-events-none text-[#d3d3d6]",
          hidden: "invisible",
        }}
      />
    </div>
  )
}

const DateRangePicker = React.forwardRef<HTMLButtonElement, DateRangePickerProps>(
  (
    {
      value,
      defaultValue,
      onValueChange,
      wrapperClassName,
      popoverClassName,
      popoverSide = "bottom",
      popoverAvoidCollisions = true,
      className,
      placeholder = DEFAULT_PLACEHOLDER,
      dateFormat = DEFAULT_FORMAT,
      minYear = 2000,
      maxYear = 2100,
      disabled,
      ...triggerProps
    },
    ref
  ) => {
    const safeMinYear = Math.min(minYear, maxYear)
    const safeMaxYear = Math.max(minYear, maxYear)

    const minMonth = React.useMemo(
      () => startOfMonth(new Date(safeMinYear, 0, 1)),
      [safeMinYear]
    )
    const maxMonth = React.useMemo(
      () => startOfMonth(new Date(safeMaxYear, 11, 1)),
      [safeMaxYear]
    )
    const minDate = React.useMemo(() => new Date(safeMinYear, 0, 1), [safeMinYear])
    const maxDate = React.useMemo(
      () => new Date(safeMaxYear, 11, 31),
      [safeMaxYear]
    )

    const years = React.useMemo(
      () =>
        Array.from(
          { length: safeMaxYear - safeMinYear + 1 },
          (_, yearIndex) => safeMinYear + yearIndex
        ),
      [safeMinYear, safeMaxYear]
    )

    const isControlled = value !== undefined
    const [internalValue, setInternalValue] = React.useState<DateRangePickerValue | undefined>(
      normalizeRange(defaultValue)
    )

    const committedValue = normalizeRange(isControlled ? value : internalValue)

    const buildPanelMonths = React.useCallback(
      (range: DateRangePickerValue | undefined) => {
        const now = startOfMonth(new Date())
        const initialStart = clampMonth(
          startOfMonth(range?.from ?? now),
          minMonth,
          maxMonth
        )

        const initialEndRaw = range?.to
          ? startOfMonth(range.to)
          : addMonths(initialStart, 1)
        const initialEnd = clampMonth(initialEndRaw, minMonth, maxMonth)

        return {
          start: initialStart,
          end: initialEnd,
        }
      },
      [minMonth, maxMonth]
    )

    const [open, setOpen] = React.useState(false)
    const [draftValue, setDraftValue] = React.useState<DateRangePickerValue | undefined>(
      committedValue
    )
    const initialMonths = buildPanelMonths(committedValue)
    const [startMonth, setStartMonth] = React.useState<Date>(initialMonths.start)
    const [endMonth, setEndMonth] = React.useState<Date>(initialMonths.end)

    const syncDraftState = React.useCallback(
      (nextValue: DateRangePickerValue | undefined) => {
        const normalized = normalizeRange(nextValue)
        setDraftValue(normalized)
        const nextMonths = buildPanelMonths(normalized)
        setStartMonth(nextMonths.start)
        setEndMonth(nextMonths.end)
      },
      [buildPanelMonths]
    )

    React.useEffect(() => {
      if (!open) {
        syncDraftState(committedValue)
      }
    }, [committedValue, open, syncDraftState])

    const handleStartMonthChange = (nextMonth: Date) => {
      setStartMonth(clampMonth(startOfMonth(nextMonth), minMonth, maxMonth))
    }

    const handleEndMonthChange = (nextMonth: Date) => {
      setEndMonth(clampMonth(startOfMonth(nextMonth), minMonth, maxMonth))
    }

    const handleStartDateSelect = (date: Date | undefined) => {
      if (!date) {
        return
      }

      setDraftValue((previousValue) => {
        const nextValue: DateRangePickerValue = {
          from: date,
          to: previousValue?.to,
        }

        if (nextValue.to && isAfter(date, nextValue.to)) {
          nextValue.to = date
        }

        return nextValue
      })
    }

    const handleEndDateSelect = (date: Date | undefined) => {
      if (!date) {
        return
      }

      setDraftValue((previousValue) => {
        const nextValue: DateRangePickerValue = {
          from: previousValue?.from,
          to: date,
        }

        if (nextValue.from && isAfter(nextValue.from, date)) {
          nextValue.from = date
        }

        return nextValue
      })
    }

    const handleCancel = () => {
      syncDraftState(committedValue)
      setOpen(false)
    }

    const handleApply = () => {
      const normalized = normalizeRange(draftValue)

      if (!isControlled) {
        setInternalValue(normalized)
      }

      onValueChange?.(normalized)
      setOpen(false)
    }

    const canApply = Boolean(draftValue?.from && draftValue?.to)
    const committedText = formatCommittedValue(committedValue, dateFormat)
    const draftText = formatDraftValue(draftValue, dateFormat)

    return (
      <div className={cn("w-full", wrapperClassName)}>
        <Popover
          open={open}
          onOpenChange={(nextOpen) => {
            if (disabled) {
              return
            }

            if (nextOpen) {
              syncDraftState(committedValue)
            }

            setOpen(nextOpen)
          }}
        >
          <PopoverTrigger asChild>
            <button
              ref={ref}
              type="button"
              disabled={disabled}
              className={cn(
                "flex h-10 w-full items-center justify-between rounded-[8px] border border-[#e6e6e6] bg-white px-3 py-2 text-left text-[14px] leading-[20px] transition-colors",
                "focus-visible:outline-none focus-visible:border-[#1D1C20] focus-visible:ring-0",
                "disabled:cursor-not-allowed disabled:bg-[#f2f2f2] disabled:text-[#9ca3af] disabled:opacity-100",
                className
              )}
              {...triggerProps}
            >
              <span
                className={cn(
                  "truncate text-[14px] font-normal leading-[20px]",
                  committedText ? "text-[#111111]" : "text-[#b3b3b3]"
                )}
              >
                {committedText || placeholder}
              </span>
              <CalendarDays className="ml-3 h-4 w-4 shrink-0 text-[#111111]" />
            </button>
          </PopoverTrigger>

          <PopoverContent
            side={popoverSide}
            avoidCollisions={popoverAvoidCollisions}
            align="start"
            sideOffset={10}
            className={cn(
              "w-[min(95vw,760px)] max-h-[var(--radix-popover-content-available-height)] overflow-y-auto overscroll-contain rounded-xl border border-[#d8d8da] bg-[#f7f7f8] p-3 shadow-[0px_12px_24px_rgba(0,0,0,0.08)] sm:p-4",
              popoverClassName
            )}
          >
            <div className="grid gap-3 md:grid-cols-2 md:gap-4">
              <CalendarPanel
                label="Start date"
                month={startMonth}
                minMonth={minMonth}
                maxMonth={maxMonth}
                minDate={minDate}
                maxDate={maxDate}
                selectedDate={draftValue?.from}
                disabledMatcher={draftValue?.to ? { after: draftValue.to } : undefined}
                disabled={disabled}
                years={years}
                onMonthChange={handleStartMonthChange}
                onSelectDate={handleStartDateSelect}
              />

              <CalendarPanel
                label="End date"
                month={endMonth}
                minMonth={minMonth}
                maxMonth={maxMonth}
                minDate={minDate}
                maxDate={maxDate}
                selectedDate={draftValue?.to}
                disabledMatcher={draftValue?.from ? { before: draftValue.from } : undefined}
                disabled={disabled}
                years={years}
                onMonthChange={handleEndMonthChange}
                onSelectDate={handleEndDateSelect}
              />
            </div>

            <div className="mt-2.5 border-t border-[#d8d8da] pt-2.5">
              <input
                readOnly
                value={draftText}
                className="h-9 w-full rounded-md border border-[#e6e6e6] bg-white px-3 py-2 text-sm leading-5 text-[#111111] outline-none transition-colors placeholder:text-[#b3b3b3] focus-visible:border-[#1D1C20]"
                aria-label="Selected date range"
              />

              <div className="mt-2.5 flex flex-col-reverse gap-2 sm:flex-row sm:justify-end">
                <Button
                  type="button"
                  variant="outline"
                  className="h-9 rounded-md px-4 text-sm"
                  onClick={handleCancel}
                >
                  Cancel
                </Button>
                <Button
                  type="button"
                  className="h-9 rounded-md px-4 text-sm"
                  disabled={!canApply}
                  onClick={handleApply}
                >
                  Apply
                </Button>
              </div>
            </div>
          </PopoverContent>
        </Popover>
      </div>
    )
  }
)

DateRangePicker.displayName = "DateRangePicker"

export { DateRangePicker }
